class Run(BaseModel):
    id: str
    script: RunScript
    version: int
    """The version the run ran."""
    environment: str
    """The environment the run ran in, under the name it had then. The environment holds the secret values and rules the run used. Choose it with the X-Environment header."""
    status: Literal["awaiting_approval", "running", "succeeded", "failed", "cancelled"]
    """The run's status. `awaiting_approval` means the run waits for a person's approval, named in `approvalRequestId`. `cancelled` means the run won't run or was stopped. For a cancelled run, `error` says why, such as a denied or expired approval, a person cancelling a long run, or a deleted environment."""
    inputs: Any = None
    output: Any = None
    """What the script returned, as JSON. It's null if the run failed."""
    error: Optional[str]
    """Why the run didn't succeed. For a failed run, this is the last lines of standard error. For a cancelled run, it says why, such as "The approval was denied". It's null while the run is in progress and once it succeeds."""
    started_by: StartedBy = Field(alias="startedBy")
    via: Literal["app", "api", "cli", "agent", "schedule", "trigger", "webhook"]
    """Where the run came from: the app, the API, the CLI, an agent connected through MCP, a schedule, an event trigger or a webhook trigger."""
    automation_name: Optional[str] = Field(alias="automationName")
    """The name of the schedule or trigger that started the run, while it exists."""
    approval_request_id: Optional[str] = Field(alias="approvalRequestId")
    """The approval request the run waits for or waited for. It's null if the run needed no approval."""
    schedule_id: Optional[str] = Field(alias="scheduleId")
    """The schedule that started the run, if one did."""
    trigger_id: Optional[str] = Field(alias="triggerId")
    """The trigger that started the run, if one did."""
    progress: Optional[float]
    """A long run's progress, from 0 to 1, as its script reported it with a `::progress 40` line on standard error."""
    progress_message: Optional[str] = Field(alias="progressMessage")
    """The message the script reported with its progress, such as `Synced 400 of 1,000 rows`."""
    test: bool
    """Whether this is a test run of a chosen version, such as a draft. A test run isn't counted as the team's use of the script."""
    log_lines: int = Field(alias="logLines")
    """How many lines the run's log has."""
    started_at: datetime = Field(alias="startedAt")
    finished_at: Optional[datetime] = Field(alias="finishedAt")
    duration_ms: Optional[int] = Field(alias="durationMs")
    """How long the run took, in milliseconds."""
    files: Optional[List[File]] = None
    """The run's files, each with a download link. These are the files given to it as file inputs (`origin: input`) and the files it saved to its /saved folder (`origin: saved`). Only a single run's read has them, not a list of runs."""


